package io.github.jtsato.walletservice.infra.database.common.filter;
import io.github.jtsato.walletservice.core.common.exception.FieldViolation; import io.github.jtsato.walletservice.core.common.exception.ValidationException; import java.util.LinkedHashMap; import java.util.List; import java.util.Optional;
public final class QuerydslFilterDefinition { private final List<QuerydslFilterFieldDefinition<?>> fields; private final java.util.Map<String, QuerydslFilterFieldDefinition<?>> byName; private QuerydslFilterDefinition(List<QuerydslFilterFieldDefinition<?>> fields, java.util.Map<String, QuerydslFilterFieldDefinition<?>> byName) { this.fields = fields; this.byName = byName; } public static QuerydslFilterDefinition of(List<QuerydslFilterFieldDefinition<?>> fields) { if (fields == null) throw error("common.querydsl.filter.definition.fields.required", "Filter fields are required."); if (fields.isEmpty()) throw error("common.querydsl.filter.definition.fields.empty", "Filter fields must not be empty."); var names = new LinkedHashMap<String, QuerydslFilterFieldDefinition<?>>(); for (var field : fields) { if (field == null) throw error("common.querydsl.filter.definition.fields.null-element", "Filter fields must not contain null elements."); if (names.putIfAbsent(field.domainName(), field) != null) throw error("common.querydsl.filter.definition.fields.duplicate", "Filter fields must not contain duplicate names."); } return new QuerydslFilterDefinition(List.copyOf(fields), java.util.Map.copyOf(names)); } public Optional<QuerydslFilterFieldDefinition<?>> findField(String domainName) { return Optional.ofNullable(byName.get(domainName)); } public List<QuerydslFilterFieldDefinition<?>> fields() { return fields; } private static ValidationException error(String key, String message) { return new ValidationException(List.of(new FieldViolation("fields", key, message))); } }
